display_yn = TRUE

    AND (
        LOWER(event_name) LIKE #{criteria.keywordPattern} ESCAPE '!'
        OR LOWER(event_place) LIKE #{criteria.keywordPattern} ESCAPE '!'
        OR LOWER(district_name) LIKE #{criteria.keywordPattern} ESCAPE '!'
        OR LOWER(addr) LIKE #{criteria.keywordPattern} ESCAPE '!'
        OR LOWER(event_type) LIKE #{criteria.keywordPattern} ESCAPE '!'

            OR event_type IN

                #{eventType}


    )


    AND event_start_date <= #{criteria.monthEnd}
    AND event_end_date >= #{criteria.monthStart}



    AND (

        (event_start_date <= #{date} AND event_end_date >= #{date})

    )


    AND event_type IN

        #{eventType}



    AND district_name = #{criteria.district}


    AND free_yn = TRUE
